CREATE OR REPLACE FUNCTION safe_register_user(p_email TEXT, p_name TEXT)
RETURNS BOOLEAN AS $$
BEGIN
    INSERT INTO users (email, name) VALUES (p_email, p_name);
    RETURN true;
EXCEPTION
    WHEN unique_violation THEN
        RAISE NOTICE 'Email % is already registered.', p_email;
        RETURN false;
    WHEN OTHERS THEN
        RAISE WARNING 'Unexpected error: %', SQLERRM;
        RETURN false;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION transfer_funds(
    p_from int,
    p_to   int,
    p_amt  numeric
)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    IF p_amt <= 0 THEN
        RAISE EXCEPTION 'Transfer amount must be positive: %', p_amt
            USING ERRCODE = '22023';
    END IF;

    UPDATE accounts SET balance = balance - p_amt WHERE id = p_from;
    UPDATE accounts SET balance = balance + p_amt WHERE id = p_to;
EXCEPTION
    WHEN foreign_key_violation THEN
        RAISE WARNING 'Unknown account, SQLSTATE=%', SQLSTATE;
        RAISE;
    WHEN others THEN
        RAISE EXCEPTION 'Transfer failed: % (SQLSTATE %)', SQLERRM, SQLSTATE;
END $$;
